        if (key.toLowerCase() === 'url') r.slug = slugOf(value)
        else r.resolved = value
        remotes.set(name, r)
      }
      for (const r of remotes.values()) if (r.resolved) return r.resolved === 'base' ? r.slug : r.resolved
